<?php
use yii\helpers\{Html,Url};$this->title='Forms';$head=$rows[0]??null;$details=$head?$head->details:[];$editing=Yii::$app->request->get('edit')||Yii::$app->request->get('new');
$titles=['RIS'=>'REQUISITION AND ISSUE SLIP','IAR'=>'INSPECTION AND ACCEPTANCE REPORT','ICS'=>'INVENTORY CUSTODIAN SLIP','PAR'=>'PROPERTY ACKNOWLEDGMENT RECEIPT','Stock Card'=>'STOCK CARD','Supply Ledger Card'=>'SUPPLIES LEDGER CARD','RSMI'=>'REPORT OF SUPPLIES AND MATERIALS ISSUED','Waste Materials Report'=>'WASTE MATERIALS REPORT','RPCI'=>'REPORT ON THE PHYSICAL COUNT OF INVENTORIES'];
$cols=['RIS'=>['Stock No.','Unit','Description','Quantity','Stock Available?','Issue Quantity','Remarks'],'IAR'=>['Item No.','Unit','Description','Quantity','Inspection Status','Acceptance Status','Remarks'],'ICS'=>['Property No.','Unit','Description','Quantity','Unit Cost','Total Amount','Remarks'],'PAR'=>['Property No.','Unit','Description','Quantity','Unit Cost','Total Amount','Remarks'],'Stock Card'=>['Date','Reference','Description','Receipt Quantity','Issue Office / Quantity','Balance Quantity','Days to Consume'],'Supply Ledger Card'=>['Date','Reference','Receipt','Issue','Balance','Days to Consume'],'RSMI'=>['RIS No.','Responsibility Center','Stock No.','Item','Unit','Quantity','Unit Cost / Amount'],'Waste Materials Report'=>['Item','Quantity','Unit','Description','Receipt / Date / Amount'],'RPCI'=>['Article','Description','Stock No.','Unit','Unit Value','Balance','On Hand','Variance / Remarks']];
?><div class="editor-actions no-print"><?=Html::a('+ New form',['index','type'=>$type,'new'=>1],['class'=>'btn primary'])?><?php if($rows):?><?=Html::a('Edit selected form',['index','type'=>$type,'ref'=>$ref,'edit'=>1],['class'=>'btn'])?><?php endif?></div><?php if($editing):?><section class="panel formpanel"><h3><?=$rows?'Edit':'New'?> <?=Html::encode($titles[$type])?></h3><form method="post" class="gridform"><?=Html::hiddenInput(Yii::$app->request->csrfParam,Yii::$app->request->csrfToken)?><?=Html::hiddenInput('old_reference',$rows?$ref:'')?><?php foreach(['reference_no'=>['Reference Number',$ref],'form_date'=>['Date',$head->date??date('Y-m-d')],'fund_cluster'=>['Fund Cluster',$details['Fund Cluster']??''],'office'=>['Office / Division',$head->office??''],'party'=>['Recipient / Party',$head->party??''],'purpose'=>['Purpose / Notes',$details['Purpose']??''],'requested_by'=>['Requested By',$details['Requested By']??''],'approved_by'=>['Approved By',$details['Approved By']??''],'issued_by'=>['Issued By',$details['Issued By']??''],'received_by'=>['Received By',$details['Received By']??'']] as $n=>$x):?><label><?=$x[0]?><input name="<?=$n?>" value="<?=Html::encode($x[1])?>" <?=$n==='reference_no'?'required':''?>></label><?php endforeach?><div style="grid-column:1/-1"><h4>Items</h4><?php $editRows=$rows?:array_fill(0,5,null);foreach($editRows as $i=>$r):$d=$r?$r->details:[];?><div class="item-row"><input name="property_number[]" value="<?=Html::encode($r->property_number??'')?>" placeholder="Stock No."><input name="unit[]" value="<?=Html::encode($d['Unit']??'')?>" placeholder="Unit"><input name="description[]" value="<?=Html::encode($r->description??'')?>" placeholder="Description"><input name="quantity[]" value="<?=Html::encode($r->quantity??'')?>" placeholder="Quantity"><input name="item_status[]" value="<?=Html::encode($r->status??'')?>" placeholder="Remarks"></div><?php endforeach?></div><button class="btn primary">Save form</button></form></section><?php endif?><div class="forms-toolbar no-print"><form><label>Form Type<select name="type" onchange="this.form.submit()"><?php foreach($types as $t):?><option value="<?=Html::encode($t)?>" <?=$t===$type?'selected':''?>><?=Html::encode($titles[$t])?></option><?php endforeach?></select></label><label>Reference Number<select name="ref" onchange="this.form.submit()"><?php foreach($refs as $rr):?><option value="<?=Html::encode($rr['reference_no'])?>" <?=$ref===$rr['reference_no']?'selected':''?>><?=Html::encode($rr['reference_no'])?> (<?=$rr['items']?> items)</option><?php endforeach?></select></label></form><button class="btn primary" onclick="window.print()">Print form</button></div><?php if(!$rows):?><section class="panel empty">No saved <?=Html::encode($titles[$type])?> record is available.</section><?php else:?><section class="paper"><div class="appendix"><?=$type==='RIS'?'Appendix 63':''?></div><div class="form-title"><img src="<?=Url::to('@web/assets/sppu/forms-dti-logo.png')?>"><div><h2><?=Html::encode($titles[$type])?></h2></div></div><table class="form-meta"><tr><td><b>Entity Name:</b> Department of Trade and Industry - Caraga</td><td><b>Fund Cluster:</b> <?=Html::encode($details['Fund Cluster']??'')?></td></tr><tr><td><b>Office / Division:</b> <?=Html::encode($head->office)?></td><td><b>Reference No.:</b> <?=Html::encode($ref)?></td></tr><tr><td><b>Date:</b> <?=Html::encode($head->date)?></td><td><b>Recipient:</b> <?=Html::encode($head->party)?></td></tr></table><table class="form-items"><thead><tr><?php foreach($cols[$type] as $c):?><th><?=Html::encode($c)?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):$d=$r->details;$base=[$r->property_number,$d['Unit']??'',$r->description,$r->quantity,'',$r->quantity,$r->status];?><tr><?php foreach(array_slice(array_pad($base,count($cols[$type]),''),0,count($cols[$type])) as $v):?><td><?=nl2br(Html::encode($v))?></td><?php endforeach?></tr><?php endforeach?><tr class="nothing"><td colspan="<?=count($cols[$type])?>">*** nothing follows ***</td></tr></tbody></table><div class="purpose"><b>Purpose / Notes:</b> <?=Html::encode($details['Purpose']??'')?></div><table class="signatures"><tr><th>Requested by</th><th>Approved by</th><th>Issued by</th><th>Received by</th></tr><tr><td><?=Html::encode($details['Requested By']??'')?></td><td><?=Html::encode($details['Approved By']??'')?></td><td><?=Html::encode($details['Issued By']??'')?></td><td><?=Html::encode($details['Received By']??$head->party)?></td></tr></table></section><?php endif?>
